sys_ui_page.processing_script:
/* global gs, x_424426_devops */
/* eslint no-undef: "error" */
(function (/** @type {GlideServletRequest} */request, /** @type {GlideServletResponse} */ response) {

	const executor = new x_424426_devops.ScriptExecutor();
	if (!executor.canExecute(this.scope)) {
		gs.addErrorMessage('This scope is not supported');
		response.sendRedirect('x_424426_devops_script_executor.do');
		return;
	}

	const result = executor.executeScript(this.scope, this.script);
	if (result.status == 'error') {
		gs.addErrorMessage(result.message);
		response.sendRedirect('x_424426_devops_script_executor.do');
		return;
	}

	gs.addInfoMessage('Script Result:<br/>' + result.script_result);
	response.sendRedirect('x_424426_devops_script_executor.do');

}).call(this, request, response); /* global request, response */
